// EDIT ME. only: [] = all; [index] = test one
const project_id = '691331356a3b9a68428ab3.43540470';
const only = [];
const shots = [
  { url: 'https://www.figma.com/api/mcp/asset/f4a7e47f-7ef0-451b-b949-14fa916717c9.png', title: 'AICHAT-1334 – Sign-in modal, Check your inbox (template)', description: 'Sign-in modal → "Check your inbox" step after a sign-in link is sent (Figma 14542:151795, "D - Account creation - By email"). Template: no frame exists yet for the new states. While resending is blocked, the line "Didn\'t receive it? Resend link" is replaced by the countdown "You can resend the link in N seconds/minutes". If too many sign-in link requests come from the same network, the error "Too many sign-in attempts from your network…" is shown in this modal.', key_ids: [972779727,972779728,972779729], tags: ['AICHAT-1334'] }
];
const rows = only.length ? shots.filter(function (s, i) { return only.indexOf(i) >= 0; }) : shots;
return rows.map(function (s) { return { json: Object.assign({ project_id: project_id }, s) }; });

const P = $('Params').all(); const items = $input.all(); const out = [];
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const p = P[i].json;
  out.push({ json: { project_id: p.project_id, title: p.title, bytes: buf.length, body: { screenshots: [{ data: 'data:image/png;base64,' + buf.toString('base64'), title: p.title, description: p.description, ocr: false, key_ids: p.key_ids, tags: p.tags || [] }] } } });
}
return out;

const T = $('To Body').all(); const res = $input.all(); const out = [];
for (let i = 0; i < res.length; i++) {
  const r = res[i].json; const b = r.body || {}; const s = (b.screenshots || [])[0] || {};
  out.push({ title: T[i] && T[i].json.title, bytes: T[i] && T[i].json.bytes, http: r.statusCode, screenshot_id: s.screenshot_id, key_ids: s.key_ids, w: s.width, h: s.height, errors: b.errors || b.error || null });
}
return [{ json: { results: out } }];
